() => {
  const root = document.getElementById('root');
  const rb = root.getBoundingClientRect();
  const out = {rootW: root.offsetWidth, rootH: root.offsetHeight, scrollH: root.scrollHeight, scrollW: root.scrollWidth, items: []};
  const sel = ['.headline','.photoband','.cands','.cta','.steps','.footer'];
  let prevBottom = null;
  for (const s of sel) {
    const e = document.querySelector(s);
    const r = e.getBoundingClientRect();
    out.items.push({s, top: +r.top.toFixed(1), bottom: +r.bottom.toFixed(1), left:+r.left.toFixed(1), right:+r.right.toFixed(1), overlapPrev: prevBottom!==null && r.top < prevBottom - 0.5});
    prevBottom = r.bottom;
  }
  // text overflow check
  document.querySelectorAll('.nm,.rl,.cta span,.step span,.footer,.headline').forEach(e=>{
    if (e.scrollWidth > e.clientWidth + 1) out.items.push({overflow: e.textContent.trim(), sw:e.scrollWidth, cw:e.clientWidth});
  });
  out.pageBottom = rb.bottom;
  return out;
}

