  document.querySelectorAll('.nm,.rl,.cta span,.step span,.footer,.headline').forEach(e=>{
    if (e.scrollWidth > e.clientWidth + 1) over.push(e.textContent.trim());
  });
  const cands = [...document.querySelectorAll('.cand')].map(e=>{const r=e.getBoundingClientRect();return [+r.left.toFixed(1),+r.width.toFixed(1)];});
  return {spacersCSSpx: sps, photoH: +ph.height.toFixed(1), rootH: root.offsetHeight, scrollH: root.scrollHeight, over, cands,
